import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextContent
from azure.core.credentials import AzureKeyCredential

from safety_models import BatchModerationRequest, BatchModerationResponse, ModerationResult, ModerationScore, HarmCategory

def moderate_batch(batch_request: BatchModerationRequest) -> BatchModerationResponse:
    endpoint = os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.environ.get("AZURE_CONTENT_SAFETY_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY must be set.")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    results: List[ModerationResult] = []

    for text_to_moderate in batch_request.texts:
        request = AnalyzeTextOptions(text=text_to_moderate)
        try:
            response = client.analyze_text(request)
            scores: List[ModerationScore] = []

            if response.hate_result:
                scores.append(ModerationScore(category=HarmCategory.HATE_SPEECH, score=response.hate_result.severity / 7.0))
            if response.self_harm_result:
                scores.append(ModerationScore(category=HarmCategory.DANGEROUS_CONTENT, score=response.self_harm_result.severity / 7.0))
            if response.sexual_result:
                scores.append(ModerationScore(category=HarmCategory.SEXUAL, score=response.sexual_result.severity / 7.0))
            if response.violence_result:
                scores.append(ModerationScore(category=HarmCategory.VIOLENCE, score=response.violence_result.severity / 7.0))

            results.append(ModerationResult(text=text_to_moderate, scores=scores, decision="SCORED"))
        except Exception as e:
            results.append(ModerationResult(text=text_to_moderate, scores=[], decision=f"ERROR: {e}"))

    return BatchModerationResponse(results=results)",
  "redact_unsafe.py": "import os
from google.cloud import dlp_v2
from safety_models import RedactionResult, RedactionSpan

def redact_unsafe(text: str, project_id: str) -> RedactionResult:
    dlp_client = dlp_v2.DlpServiceClient()
    parent = f"projects/{project_id}"

    custom_info_type = dlp_v2.CustomInfoType(
        info_type=dlp_v2.InfoType(name="UNSAFE_WORDS_CUSTOM"),
        dictionary=dlp_v2.CustomInfoType.Dictionary(
            word_list=dlp_v2.CustomInfoType.Dictionary.WordList(
                words=["badword", "illegalterm", "hatephrase", "profanity", "violence"] # Example unsafe words
            )
        )
    )

    inspect_config = dlp_v2.InspectConfig(
        info_types=[
            dlp_v2.InfoType(name="EMAIL_ADDRESS"),
            dlp_v2.InfoType(name="PHONE_NUMBER"),
            dlp_v2.InfoType(name="CREDIT_CARD_NUMBER"),
        ],
        custom_info_types=[custom_info_type],
        min_likelihood=dlp_v2.Likelihood.POSSIBLE,
        include_quote=True,
    )

    item = dlp_v2.ContentItem(value=text)

    inspect_response = dlp_client.inspect_content(
        request=dlp_v2.InspectContentRequest(
            parent=parent,
            inspect_config=inspect_config,
            item=item
        )
    )

    redaction_spans = []
    redacted_text_list = list(text)

    findings = sorted(inspect_response.result.findings, key=lambda f: f.location.byte_range.start, reverse=True)

    for finding in findings:
        start = finding.location.byte_range.start
        end = finding.location.byte_range.end
        original_span = text[start:end]

        replacement_char = "*"
        redacted_span_str = replacement_char * (end - start)
        redacted_text_list[start:end] = list(redacted_span_str)

        redaction_spans.append(RedactionSpan(
            start=start,
            end=end,
            original_text=original_span,
            redacted_text=redacted_span_str
        ))

    final_redacted_text = "".join(redacted_text_list)

    return RedactionResult(original_text=text, redacted_text=final_redacted_text, spans=redaction_spans)",
  "safety_threshold.py": "import os
import json
import boto3

from safety_models import ModerationScore, ModerationDecision, HarmCategory, ModerationResult

def get_aws_secrets_manager_client():
    region = os.environ.get("AWS_REGION", "us-east-1")
    return boto3.client("secretsmanager", region_name=region)

def get_thresholds(secret_name: str) -> dict:
    secrets_client = get_aws_secrets_manager_client()
    try:
        get_secret_value_response = secrets_client.get_secret_value(
            SecretId=secret_name
        )
        if 'SecretString' in get_secret_value_response:
            return json.loads(get_secret_value_response['SecretString'])
        else:
            raise ValueError("SecretString not found in AWS Secrets Manager response.")
    except Exception as e:
        print(f"Error fetching secret '{secret_name}': {e}")
        return {
            HarmCategory.TOXICITY.value: 0.8,
            HarmCategory.SEXUAL.value: 0.7,
            HarmCategory.VIOLENCE.value: 0.8,
            HarmCategory.HARASSMENT.value: 0.8,
            HarmCategory.HATE_SPEECH.value: 0.75,
            HarmCategory.DANGEROUS_CONTENT.value: 0.85,
        }

def apply_safety_thresholds(
    moderation_result: ModerationResult,
    secret_name: str = "safety-thresholds"
) -> ModerationDecision:

    thresholds = get_thresholds(secret_name)

    overall_decision = "ALLOW"
    violation_reasons = []

    for score_item in moderation_result.scores:
        category_threshold = thresholds.get(score_item.category.value, 1.0)
        if score_item.score >= category_threshold:
            overall_decision = "BLOCK"
            violation_reasons.append(f"{score_item.category.value} score ({score_item.score:.2f}) exceeds threshold ({category_threshold:.2f})")

    reason_str = ", ".join(violation_reasons) if violation_reasons else "No violations detected."

    return ModerationDecision(
        text=moderation_result.text,
        decision=overall_decision,
        reason=reason_str
    )",
